{
  "verdict": "request_changes",
  "summary": "Candidate implements active() using a non-strict inequality, incorrectly marking tokens as active at the expiry timestamp, which violates the contract.",
  "findings": [
    {
      "finding_id": "f1",
      "file": "candidate.py",
      "line_start": 2,
      "line_end": 2,
      "severity": "high",
      "description": "active() returns True when now == expires_at, but the spec requires the token to be inactive at or after expires_at.",
      "evidence": "active(10, 10) evaluates to True, whereas it should be False per the spec, which defines activity strictly before expires_at."
    }
  ]
}
